export function t(value){return language==='zh'?(dictionary.get(value)||value):value;}
export function localize(root=document.body){
  document.documentElement.lang=language==='zh'?'zh-CN':'en';
  root.querySelectorAll?.('[lang]').forEach(el=>el.lang=document.documentElement.lang);
  if(language!=='zh')return;
  const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let node;
  while((node=walker.nextNode())){if(node.parentElement?.closest('[data-no-translate],.code-backdrop,svg,script,style'))continue;const raw=node.textContent,key=raw.trim();if(dictionary.has(key))node.textContent=raw.replace(key,dictionary.get(key));}
  root.querySelectorAll?.('[aria-label],[title],[alt]').forEach(el=>{if(el.closest('[data-no-translate],.code-backdrop'))return;for(const attr of ['aria-label','title','alt']){const value=el.getAttribute(attr);if(value&&dictionary.has(value))el.setAttribute(attr,dictionary.get(value));else if(value?.endsWith(' official promotional artwork'))el.setAttribute(attr,t(value.replace(' official promotional artwork',''))+' 官方宣传图');else if(attr==='aria-label'&&/^View .+ project$/.test(value||''))el.setAttribute(attr,'查看 '+value.slice(5,-8)+' 作品');}});
}
